// RequiredCapForMCPTool returns the capability required to invoke
// tool, and whether tool is a known tool at all. An unknown tool name
// is treated by callers as admin-only (fail closed), never as "no
// capability required."
func RequiredCapForMCPTool(tool string) (string, bool) {
	c, ok := MCPToolCap[tool]
	return c, ok
}
